package com.bcsystems.siga.controller;
import com.bcsystems.siga.domain.*; import com.bcsystems.siga.domain.en.EstadoDeduccion; import com.bcsystems.siga.dto.*; import com.bcsystems.siga.repository.DeduccionRepository; import com.bcsystems.siga.service.NominaService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/deduccion") public class DeduccionController { private final NominaService s; private final DeduccionRepository r; public DeduccionController(NominaService s,DeduccionRepository r){this.s=s;this.r=r;} @GetMapping @PreAuthorize("hasAuthority('DEDUCCIONES_VER')") public List<ConceptoManualResponse> listar(){return s.listarDeducciones().stream().map(x->new ConceptoManualResponse(x.getIdDeduccion(),x.getPersona().getIdPersona(),x.getPersona().getNombre()+" "+x.getPersona().getApellido(),x.getConcepto(),x.getMonto(),x.getFecha(),x.getEstado().name(),x.getOrigen().name())).toList();} @PostMapping @PreAuthorize("hasAuthority('DEDUCCIONES_CREAR')") public Deduccion crear(@RequestBody DeduccionRequest x){return s.crearDeduccion(x);} @PutMapping("/{id}") @PreAuthorize("hasAuthority('DEDUCCIONES_CREAR')") public Deduccion editar(@PathVariable Long id,@RequestBody DeduccionRequest x){return s.actualizarDeduccion(id,x);} @DeleteMapping("/{id}") @PreAuthorize("hasAuthority('DEDUCCIONES_CREAR')") public void eliminar(@PathVariable Long id){s.eliminarDeduccion(id);} @PostMapping("/{id}/aprobar") @PreAuthorize("hasAuthority('DEDUCCIONES_REVISAR')") public Deduccion aprobar(@PathVariable Long id){return cambiar(id,EstadoDeduccion.APROBADA);} @PostMapping("/{id}/rechazar") @PreAuthorize("hasAuthority('DEDUCCIONES_REVISAR')") public Deduccion rechazar(@PathVariable Long id){return cambiar(id,EstadoDeduccion.RECHAZADA);} @PostMapping("/{id}/cancelar") @PreAuthorize("hasAuthority('DEDUCCIONES_REVISAR')") public Deduccion cancelar(@PathVariable Long id){return cambiar(id,EstadoDeduccion.CANCELADA);} private Deduccion cambiar(Long id,EstadoDeduccion e){Deduccion d=r.findById(id).orElseThrow();if(d.getNomina()!=null)throw new IllegalArgumentException("La deducción ya está ligada a una nómina");d.setEstado(e);return r.save(d);}}
